entries[390710] = { ["name"] = "Greatstaff's Wrath", ["text"] = "Unlimited range\nInstant\nIncreases Greatstaff of the Broodkeeper's damage done by 10%. This effect stacks.\n\nPlayers may cast Focus Greatstaff while near the embedded weapon, consuming one application of Greatstaff's Wrath and causing a beam to pursue the player.\n\nThe focused beam inflicts 123660 Nature damage to players within 3 yards every half-second during pursuit, shattering any egg in its path. Shattering an egg incurs Clutchwatcher's Rage." }
entries[390711] = { ["name"] = "Empowered Greatstaff's Wrath", ["text"] = "Unlimited range\nInstant\nIncreases Empowered Greatstaff of the Broodkeeper's damage done by 30%. This effect stacks, beginning at 2 charges.\n\nDiurna empowers the embedded weapon, invoking its wrath, consuming one application of Empowered Greatstaff's Wrath for each targeted player, causing a beam to pursue them.\n\nThe focused beam inflicts 141326 Nature damage to players within 3 yards every half-second during pursuit, shattering any egg in its path. Shattering an egg incurs Clutchwatcher's Rage." }
